// <auto-generated />
import { useCallback, useEffect, useRef, useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import type { UseQueryOptions } from '@tanstack/react-query';
import { useApiService } from './useApiService';
import { ApiError } from '../errors/ApiError';
import type { Item, ItemLog, ItemLogs, Items, PaginationResult } from '../models';

const itemsKeys = {
  all: ['items'] as const,
  getItemLogs: (itemId: string, query?: { logLevel?: 'debug' | 'info' | 'warn' | 'error'; from?: Date }) => [...itemsKeys.all, 'getItemLogs', itemId, query] as const,
  search: (query?: { createdAfter?: Date; createdBefore?: Date }) => [...itemsKeys.all, 'search', query] as const,
};

export { itemsKeys };

export function useListItemsStream(query?: { filter?: string }, options?: { enabled?: boolean }) {
  const api = useApiService();
  const [items, setItems] = useState<readonly Item[]>([]);
  const [status, setStatus] = useState<'idle' | 'streaming' | 'success' | 'error'>('idle');
  const [error, setError] = useState<Error | null>(null);
  const controllerRef = useRef<AbortController | null>(null);

  const cancel = useCallback(() => {
    controllerRef.current?.abort();
    controllerRef.current = null;
    setStatus('idle');
  }, []);

  const reset = useCallback(() => {
    cancel();
    setItems([]);
    setError(null);
  }, [cancel]);

  const enabled = options?.enabled !== false;
  const keyDep = JSON.stringify({ query });

  useEffect(() => {
    if (!enabled) return;

    const controller = new AbortController();
    controllerRef.current = controller;
    setStatus('streaming');
    setItems([]);
    setError(null);

    let buffer: Item[] = [];
    (async () => {
      try {
        for await (const item of api.items.listItems(query, controller.signal)) {
          if (controller.signal.aborted) return;
          buffer = [...buffer, item];
          setItems(buffer);
        }
        if (!controller.signal.aborted) setStatus('success');
      } catch (err) {
        if (controller.signal.aborted) return;
        if (err instanceof DOMException && err.name === 'AbortError') return;
        setError(err as Error);
        setStatus('error');
      }
    })();

    return () => controller.abort();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [enabled, keyDep]);

  return { items, status, error, cancel, reset };
}

